function normalizeLegacyArabicToPersian(text) {
  if (!text) return text;
  let normalized = text;
  guideArabicToPersianReplacements.forEach(([from, to]) => {
    normalized = normalized.split(from).join(to);
  });
  return normalized;
}

function resolveGuideTranslation(base, lang, locale) {
  if (lang === "tr") return base;
  if (lang === "fa" && guideFaOverrides[base]) return guideFaOverrides[base];
  if (lang === "fa" && guideFaExtraOverrides[base]) return guideFaExtraOverrides[base];
  const translated = (locale && locale[lang]) || base;
  return lang === "fa" ? normalizeLegacyArabicToPersian(translated) : translated;
}

