function applyGuideLocaleTranslations(locale, entries) {
  Object.entries(entries).forEach(([base, value]) => {
    guideLiteralTranslations[base] = {
      ...(guideLiteralTranslations[base] || {}),
      [locale]: value,
    };
  });
}

function applyGuideEnglishTranslations(entries) {
  applyGuideLocaleTranslations("en", entries);
}

