  "Nasıl çalışıyoruz?": "Как мы работаем?",
  "İlk temastan düzenli takibe kadar tek sistem": "Единая система от первого контакта до регулярного сопровождения",
  "Amacımız dosyayı büyütmek değil, süreci sadeleştirip sizi doğru noktaya hızlıca ulaştırmak.": "Наша цель не усложнять процесс, а упростить его и быстро привести вас к правильному решению.",
  "İlk görüşme": "Первая встреча",
  "İhtiyacı dinler, dosyanın ana başlığını ve öncelikli adımlarını netleştiririz.": "Мы выслушиваем потребность и определяем главный фокус проекта и приоритетные шаги.",
  "Doğru yapı": "Правильная структура",
  "Kuruluş, vergi ve operasyon tarafında uygun çerçeveyi kurup dosyayı sağlıklı zemine oturturuz.": "Мы выстраиваем подходящую рамку для регистрации, налогов и операционной части и ставим процесс на здоровую основу.",
  "Düzenli takip": "Регулярное сопровождение",
  "Belgeler, resmi adımlar ve günlük mali süreçler aynı çizgide ilerler; iletişim düzenli kalır.": "Документы, официальные шаги и ежедневные финансовые процессы идут в одной логике, а коммуникация остается регулярной.",
  "İlk görüşmede çerçeveyi netleştirelim": "Давайте определим рамки уже на первой встрече",
  "Kuruluş, vergi, bordro veya genel mali takip için doğru başlangıcı birlikte kuralım.": "Давайте вместе заложим правильный старт для регистрации, налогов, зарплаты или общего финансового сопровождения.",
  "İlk Çerçeve": "Первая рамка",
  "Net Başlangıç": "Ясный старт",
  "Düzenli İletişim": "Регулярная связь",
