  "“Avantajlı vergi yapısı” ifadesi tek başına yeterli karar sebebi olmamalıdır.": "Фраза \"выгодная налоговая структура\" сама по себе не должна быть достаточным основанием для решения.",
  "Güncel mevzuat, uygulama şartları ve dosya bazlı uygunluk ayrıca teyit edilmelidir.": "Актуальное законодательство, практические условия и пригодность для конкретного кейса нужно подтверждать отдельно.",
  "UİŞ değerlendirmesinde izlediğimiz tipik akış": "Типовой порядок нашей оценки UİŞ",
