  "Not: UİŞ ile ilgili güncel uygunluk, vergi rejimi, operasyon kapsamı ve belge listesi dosya bazında değişebilir. Nihai karar öncesinde güncel mevzuat ve uygulama şartlarının teyit edilmesi gerekir.": "Примечание: актуальная применимость UİŞ, налоговый режим, объем операций и список документов могут отличаться в зависимости от кейса. Перед окончательным решением нужно подтвердить действующие нормы и практические условия.",
