  "Not: Nihai yapı seçimi yalnızca genel avantaj listesiyle değil, faaliyet kapsamı, hissedar profili, banka akışı, resmi uygunluk ve güncel mevzuat değerlendirmesiyle yapılmalıdır.": "Примечание: окончательный выбор структуры должен основываться не только на списке общих преимуществ, но и на анализе масштаба деятельности, профиля акционеров, банковского потока, официального соответствия и актуального законодательства.",
