  "Kaya Plus'ın gerçek ofis altyapısı, düzenli süreç yaklaşımı ve yerli-yabancı yatırımcıya uygun danışmanlık çizgisini tek sayfada görün.": "زیرساخت واقعی دفتر کایا پلاس، رویکرد منظم آن به فرایندها و شیوه مشاوره مناسب برای سرمایه‌گذار داخلی و خارجی را در یک صفحه ببینید.",

  // Services
  "Hizmetler | Kaya Plus": "خدمات | Kaya Plus",
  "Hizmetlerimiz": "خدمات ما",
  "Kuruluş, muhasebe, vergi, bordro ve mali danışmanlık başlıklarını daha görünür, daha sade ve daha güven veren bir akışla yönetiyoruz.": "سرفصل‌های تأسیس، حسابداری، مالیات، حقوق و دستمزد و مشاوره مالی را در مسیری شفاف‌تر، ساده‌تر و اعتمادآفرین‌تر مدیریت می‌کنیم.",
  "İşletmenin günlük kayıt düzeninden stratejik vergi planına, bordro takibinden kuruluş sürecine kadar ihtiyaç duyduğu başlıkları tek çatı altında, daha sade ve daha görünür bir akışla yönetiyoruz.": "از نظم روزانه ثبت‌ها تا برنامه‌ریزی راهبردی مالیات، و از پیگیری حقوق و دستمزد تا فرایند تأسیس، همه نیازهای کسب‌وکار را زیر یک سقف و در مسیری ساده‌تر و شفاف‌تر مدیریت می‌کنیم.",
  "Kuruluş, danışmanlık ve yapı desteği": "تأسیس، مشاوره و پشتیبانی ساختار",
  "Tek temas noktası": "یک نقطه تماس واحد",
  "Kuruluş ve yapı seçimi": "تأسیس و انتخاب ساختار",
  "Kuruluşta amaç yalnızca başvuru yapmak değil, doğru yapıyla başlamaktır. Modeli sonraki mali düzenle birlikte okuruz.": "در تأسیس، هدف فقط ارائه درخواست نیست؛ بلکه شروع با ساختار درست است. ما مدل انتخابی را همراه با نظم مالی بعدی بررسی می‌کنیم.",
  "Yerel limited, yabancı şube veya doğru başlangıç modeli için dosyanın çerçevesini en başta netleştiririz. Yeni şirket, ortaklık değişimi veya yabancı yatırımcı teması varsa bu başlık daha çok öne çıkar.": "برای شرکت محدود محلی، شعبه خارجی یا مدل درست شروع، چارچوب پرونده را از همان ابتدا روشن می‌کنیم. اگر شرکت جدید، تغییر شراکت یا سرمایه‌گذار خارجی مطرح باشد، این سرفصل اهمیت بیشتری پیدا می‌کند.",
  "Yapı seçimini, evrak ve başvuru sırasını, kuruluş sonrası ilk adımları birlikte planlarız.": "انتخاب ساختار، ترتیب مدارک و درخواست‌ها و نخستین گام‌های پس از تأسیس را با هم برنامه‌ریزی می‌کنیم.",
  "Bu başlık özellikle yeni şirket kuruluşlarında, ortaklık yapısı değiştiğinde veya yabancı yatırımcıyla başlangıç planlandığında daha fazla önem kazanır.": "این سرفصل به‌ویژه در ثبت شرکت جدید، تغییر ساختار شراکت یا آغاز کار با سرمایه‌گذار خارجی اهمیت بیشتری پیدا می‌کند.",
  "Muhasebe": "حسابداری",
  "Kayıt düzenini kurar, mali tabloyu daha okunur hale getiririz. Günlük akış ile dönem sonu aynı zeminde ilerler.": "نظم ثبت‌ها را برقرار می‌کنیم و تصویر مالی را خواناتر می‌سازیم. جریان روزانه و پایان دوره در یک چارچوب واحد پیش می‌روند.",
  "Gelirin, giderin ve mali ritmin daha sade okunmasını hedefleriz. Kayıt düzeni kurulduğunda şirket sahibi yalnızca evrak değil, daha anlaşılır bir mali görünürlük de kazanır.": "هدف ما این است که درآمد، هزینه و ریتم مالی شفاف‌تر خوانده شود. وقتی نظم ثبت‌ها شکل بگیرد، صاحب کسب‌وکار فقط اسناد مرتب ندارد، بلکه دید مالی روشن‌تری هم به‌دست می‌آورد.",
  "Aylık kayıt takibini, gelir-gider görünürlüğünü ve dönemsel mali veri düzenini aynı çerçevede toplarız.": "پیگیری ماهانه ثبت‌ها، شفافیت درآمد و هزینه و نظم داده‌های مالی دوره‌ای را در یک چارچوب جمع می‌کنیم.",
  "Böylece şirket sahibi geliri, gideri ve dönemsel mali ritmi daha net okuyabilir.": "به این ترتیب صاحب شرکت می‌تواند درآمد، هزینه و ریتم مالی دوره‌ای را واضح‌تر ببیند.",
  "Vergi ve Uyum": "مالیات و انطباق",
  "Vergi ve resmi takip": "پیگیری مالیات و امور رسمی",
  "Vergi, tasdik ve resmi sorumlulukları tek takvimde toplarız. Amaç, uyum tarafını dağılmadan yürütmektir.": "مالیات، تأییدات و مسئولیت‌های رسمی را در یک تقویم واحد جمع می‌کنیم تا بخش انطباق بدون پراکندگی پیش برود.",
  "Tarihleri, beyanları ve resmi akışı tek yerde tutarız. Kuruluş sonrası takvim, beyan ve resmi takip başlıklarını dağılmadan planladığımız için süreç daha kontrollü ilerler.": "تاریخ‌ها، اظهارنامه‌ها و جریان رسمی را در یک نقطه نگه می‌داریم. چون تقویم، اظهارها و پیگیری رسمی پس از تأسیس را یکپارچه برنامه‌ریزی می‌کنیم، فرایند با کنترل بیشتری پیش می‌رود.",
  "Vergi uyumunu, tasdik desteğini ve resmi süreç takibini aynı düzen içinde yönetiriz.": "انطباق مالیاتی، پشتیبانی تأییدات و پیگیری فرایندهای رسمی را در یک نظم واحد مدیریت می‌کنیم.",
  "Buradaki amaç, tarihleri ve beyanları tek yerde tutarak sürecin dağılmasını önlemektir.": "هدف در اینجا آن است که با نگه‌داشتن تاریخ‌ها و اظهارها در یک جا، از پراکندگی فرایند جلوگیری شود.",
  "Bordro": "حقوق و دستمزد",
  "Bordro ve personel akışı": "جریان حقوق و دستمزد و امور پرسنل",
  "Bordro tarafında maaş, sosyal sigorta ve personel hareketlerini birlikte izleriz. Böylece ekip büyüdükçe düzen korunur.": "در بخش حقوق و دستمزد، حقوق، بیمه اجتماعی و جابه‌جایی‌های پرسنل را با هم پیگیری می‌کنیم تا با رشد تیم، نظم حفظ شود.",
  "Ekip sayısı artan veya personel hareketi yoğun olan yapılarda bordro akışının dağılmaması kritik hale gelir. Maaş, sosyal sigorta ve personel takibini aynı çerçevede tutarız.": "در ساختارهایی که تعداد نیروها افزایش می‌یابد یا جابه‌جایی پرسنل زیاد است، پراکنده نشدن جریان حقوق و دستمزد حیاتی می‌شود. ما حقوق، بیمه اجتماعی و پیگیری پرسنل را در یک چارچوب نگه می‌داریم.",
  "Maaş ve bordro takibini, sosyal sigorta akışını ve personel giriş-çıkış sürecini aynı düzen içinde toplarız.": "پیگیری حقوق و دستمزد، جریان بیمه اجتماعی و فرایند ورود و خروج کارکنان را در یک نظم واحد جمع می‌کنیم.",
  "Bu akış özellikle ekip büyüdüğünde, işe giriş-çıkış hareketi yoğunlaştığında veya personel takibini tek yerde tutmak gerektiğinde kritik hale gelir.": "این جریان به‌ویژه زمانی که تیم بزرگ‌تر می‌شود، رفت‌وآمد نیروی انسانی افزایش می‌یابد یا لازم است پیگیری پرسنل در یک نقطه متمرکز بماند، اهمیت حیاتی پیدا می‌کند.",
  "Danışmanlık": "مشاوره",
