  "Müşterileri ağırlıklı olarak KKTC dışındaysa ve gelir akışı sınır ötesi kurgulanıyorsa UİŞ seçeneği gündeme gelir.": "اگر بیشتر مشتریان خارج از قبرس شمالی باشند و جریان درآمد ماهیت فرامرزی داشته باشد، گزینه UİŞ مطرح می‌شود.",
