  "Faaliyetin kapsamı baştan doğru tanımlanırsa sonraki muhasebe ve uyum akışı daha düzenli kurulur.": "اگر دامنه فعالیت از ابتدا درست تعریف شود، جریان بعدی حسابداری و انطباق منظم‌تر شکل می‌گیرد.",
