  "Not: Nihai yapı seçimi yalnızca genel avantaj listesiyle değil, faaliyet kapsamı, hissedar profili, banka akışı, resmi uygunluk ve güncel mevzuat değerlendirmesiyle yapılmalıdır.": "نکته: انتخاب نهایی ساختار نباید فقط بر اساس فهرست کلی مزایا انجام شود؛ بلکه باید دامنه فعالیت، پروفایل سهامداران، جریان بانکی، انطباق رسمی و مقررات روز نیز بررسی شود.",
  "Dosyanıza göre doğru yapıyı netleştirelim": "بیایید بر اساس پرونده شما ساختار درست را روشن کنیم",
  "Yerel limited, UİŞ ve yabancı şirket şubesi seçeneklerini sizin iş modelinize göre birlikte okuyup sade bir karar çerçevesi çıkarabiliriz.": "می‌توانیم گزینه‌های شرکت محدود محلی، UİŞ و شعبه شرکت خارجی را بر اساس مدل کسب‌وکار شما با هم بررسی کنیم و یک چارچوب تصمیم‌گیری ساده و روشن بسازیم.",
  "Karşılaştırmalı Görüşme Al": "درخواست جلسه مقایسه‌ای",
  "KKTC'de yerel limited, UİŞ ve yabancı şirket şubesi yapılarını hangi yatırımcı profilinin tercih edebileceğini karşılaştırmalı olarak görün.": "به‌صورت مقایسه‌ای ببینید چه نوع سرمایه‌گذاری در قبرس شمالی معمولاً شرکت محدود محلی، UİŞ یا شعبه شرکت خارجی را ترجیح می‌دهد.",

  // Formation requirements
