  "Kuzey Kıbrıs'ta şirket kuruluşu ve faaliyetleri, başta Şirketler Yasası (Fasıl 113) olmak üzere Gelir ve Vergi Yasası, Katma Değer Vergisi Yasası, Vergi Usul Yasası, Sosyal Sigortalar Yasası ve İhtiyat Sandığı Yasası kapsamında düzenlenmektedir.": "تأسیس و فعالیت شرکت‌ها در قبرس شمالی در چارچوب قانون شرکت‌ها (فصل ۱۱۳) و همچنین قانون مالیات بر درآمد، قانون مالیات بر ارزش افزوده، قانون آیین مالیاتی، قانون بیمه‌های اجتماعی و قانون صندوق احتیاط تنظیم می‌شود.",
