  "Limited şirket kuruluşu, tescil, unvan, faaliyet alanı ve sermaye yapısının temel yasal çerçevesini belirler.": "چارچوب قانونی پایه برای تأسیس، ثبت، نام شرکت، حوزه فعالیت و ساختار سرمایه شرکت با مسئولیت محدود را تعیین می‌کند.",
