  "4. Yabancı yatırımcılar için kısa not": "۴. یادداشت کوتاه برای سرمایه‌گذاران خارجی",
  "Yabancı yatırımcılar açısından da yasal çerçeve açıktır; gerekli izinler doğrultusunda yabancı sermayeli şirket kurulabilir. Tüm bu süreçlerin doğru ve eksiksiz yürütülmesi için profesyonel mali danışmanlık desteği büyük önem taşır.": "از منظر سرمایه‌گذاران خارجی نیز چارچوب قانونی روشن است؛ با اخذ مجوزهای لازم می‌توان شرکت با سرمایه خارجی ثبت کرد. برای پیشبرد درست و کامل همه این فرایندها، پشتیبانی حرفه‌ای مشاوره مالی اهمیت زیادی دارد.",
  "Yabancı ortaklı veya tamamen yabancı sermayeli şirket kurulabilir": "می‌توان شرکت با شریک خارجی یا کاملاً با سرمایه خارجی تأسیس کرد",
