  "Önemli not: Yasalar, uygulama detayları, lisans gereklilikleri ve resmi prosedürler zaman içinde değişebilir. İşlem öncesinde güncel mevzuat teyidi yapılmalıdır.": "نکته مهم: قوانین، جزئیات اجرایی، الزامات مجوزها و رویه‌های رسمی ممکن است با گذر زمان تغییر کنند. پیش از هر اقدام، باید مقررات روز تأیید شود.",
