  // Legislation hub
  "Mevzuat Rehberi | Kaya Plus": "راهنمای مقررات | Kaya Plus",
  "Kuruluş, vergi ve resmi süreçler için mevzuat başlıklarını tek yerde görün": "سرفصل‌های مقررات مربوط به تأسیس، مالیات و فرایندهای رسمی را در یک جا ببینید",
  "Bu merkez; KKTC’de şirket kurmayı, mali düzen kurmayı veya mevcut işleyişini daha disiplinli takip etmeyi hedefleyen işletmeler için mevzuat başlıklarını ana kümeler halinde sunar.": "این مرکز، سرفصل‌های مقررات را در قالب خوشه‌های اصلی برای کسب‌وکارهایی ارائه می‌کند که می‌خواهند در قبرس شمالی شرکت ثبت کنند، نظم مالی بسازند یا روند فعلی خود را با انضباط بیشتری دنبال کنند.",
