  "Yeni bir şirket kurulacaksa, mevcut yabancı şirket KKTC’de yapılandırılacaksa veya ticari model farklı bir şirket tipine taşınacaksa bu başlık öne çıkar.": "اگر قرار است شرکت جدیدی ثبت شود، شرکت خارجی موجود در قبرس شمالی ساختاربندی شود یا مدل تجاری به نوع دیگری از شرکت منتقل گردد، این سرفصل در اولویت قرار می‌گیرد.",
