  "Önemli not: Vergi oranları, uygulama detayları, bildirim usulleri ve resmi prosedürler zaman içinde değişebilir. Bu rehber merkezi genel yönlendirme içindir; işlem öncesi güncel mevzuat teyidi yapılmalıdır.": "نکته مهم: نرخ‌های مالیاتی، جزئیات اجرایی، روش‌های اعلام و رویه‌های رسمی ممکن است در طول زمان تغییر کنند. این مرکز صرفاً برای راهنمایی عمومی است و پیش از هر اقدام باید مقررات روز تأیید شوند.",
