  "Bu yapı, yurt dışı odaklı faaliyet modelinde farklı bir vergi mantığı sunar; ancak uygunluk mutlaka faaliyet yönü ve dosya bazında değerlendirilmelidir.": "این ساختار در مدل‌های فعالیت برون‌گرا منطق مالیاتی متفاوتی ارائه می‌دهد، اما تناسب آن باید حتماً بر اساس جهت فعالیت و خود پرونده ارزیابی شود.",
