  "Sermaye şirketleri, kooperatifler ve kamu iktisadi kuruluşları vergilendirilir.": "شرکت‌های سرمایه‌ای، تعاونی‌ها و نهادهای اقتصادی عمومی را مشمول مالیات می‌داند.",
  "Şirketlerin elde ettiği net kazanç üzerinden vergi alınır.": "مالیات بر اساس سود خالص به‌دست‌آمده شرکت‌ها اخذ می‌شود.",
  "Kamu yararına faaliyet gösteren bazı kurumlara muafiyet tanınabilir.": "برای برخی نهادهایی که در راستای منافع عمومی فعالیت می‌کنند، معافیت‌هایی ممکن است در نظر گرفته شود.",
  "Bu düzenleme, ticari faaliyet yürüten şirketlerin vergi yükümlülüklerini belirler.": "این مقرره، تعهدات مالیاتی شرکت‌هایی را که فعالیت تجاری دارند مشخص می‌کند.",
