  "Belirli işlemler için istisna ve indirim mekanizmaları uygulanır.": "برای برخی معاملات، سازوکارهای معافیت و تخفیف اعمال می‌شود.",
  "KDV, tüketim üzerinden alınan temel dolaylı vergidir.": "VAT مالیات غیرمستقیم پایه‌ای است که بر مصرف دریافت می‌شود.",
  "Bu yasa, telekomünikasyon sektöründe sunulan hizmetlerin vergilendirilmesini düzenler.": "این قانون مالیات‌گذاری بر خدمات ارائه‌شده در بخش مخابرات را تنظیم می‌کند.",
  "Mobil iletişim, internet ve diğer haberleşme hizmetleri vergilendirilir.": "ارتباطات موبایلی، اینترنت و سایر خدمات ارتباطی را مشمول مالیات می‌داند.",
  "Vergi yükümlüsü, bu hizmetleri sunan işletmelerdir.": "مؤدی مالیاتی، کسب‌وکارهایی هستند که این خدمات را ارائه می‌کنند.",
  "Vergi, sunulan hizmet karşılığında elde edilen gelir üzerinden hesaplanır.": "مالیات بر اساس درآمد حاصل از خدمات ارائه‌شده محاسبه می‌شود.",
  "Yasa, iletişim sektöründeki özel vergi çerçevesini netleştirir.": "این قانون چارچوب مالیاتی ویژه بخش ارتباطات را روشن می‌کند.",
  "Finans sektörüne yönelik özel bir vergi düzenlemesidir.": "این یک مقرره مالیاتی ویژه برای بخش مالی است.",
  "Bankacılık, sigortacılık ve finansal işlemler vergilendirilir.": "بانکداری، بیمه‌گری و عملیات مالی را مشمول مالیات می‌کند.",
  "Faiz gelirleri, komisyonlar ve benzeri kazançlar vergiye tabidir.": "درآمد بهره، کمیسیون‌ها و عایدی‌های مشابه مشمول مالیات هستند.",
  "Vergi, finans kuruluşlarının elde ettiği gelirler üzerinden alınır.": "مالیات بر اساس درآمد کسب‌شده توسط مؤسسات مالی اخذ می‌شود.",
