  "Muafiyet ve indirim uygulamaları belirli şartlara bağlıdır.": "معافیت‌ها و تخفیف‌ها به شرایط مشخصی وابسته‌اند.",
  "Başlık, miras ve vefat sonrası doğan vergisel süreçlerin ana çerçevesini ortaya koyar.": "این سرفصل چارچوب اصلی فرایندهای مالیاتی مربوط به ارث و پس از فوت را ترسیم می‌کند.",
  "Ticaret, şirketler ve finans mevzuatı": "مقررات تجارت، شرکت‌ها و مالی",
