  "Komandit şirketlerde sınırlı ve sınırsız sorumluluk birlikte bulunur.": "در شرکت‌های مختلط، مسئولیت محدود و نامحدود به‌طور هم‌زمان وجود دارد.",
  "Ortakların temsil yetkileri, sorumlulukları ve yükümlülükleri detaylı şekilde düzenlenmiştir.": "اختیارات نمایندگی، مسئولیت‌ها و تعهدات شرکا به‌صورت دقیق تنظیم شده‌اند.",
  "Ortaklık temelli işletme modelleri için sorumluluk paylaşımını ve temsil yapısını belirleyen ana çerçevedir.": "این چارچوب اصلی تقسیم مسئولیت و ساختار نمایندگی را برای مدل‌های کسب‌وکار مبتنی بر شراکت تعیین می‌کند.",
