const guideTextSelector = [
  ".brand-sub",
  ".topbar-links a",
  ".mobile-nav a",
  ".eyebrow",
  "h1",
  ".lead",
  ".fact-label",
  ".fact-card strong",
  ".hero-media-badge strong",
  ".hero-media-badge span",
  ".hero-actions a",
  ".card-eyebrow",
  ".card-title",
  ".qi-label",
  ".qi-sub",
  ".response-note-text",
  ".channel-label",
  ".ch-meta",
  ".status-chip-text",
  ".btn-map-label",
  ".law-accordion-head span",
  ".gl-kicker",
  ".gl-about-kicker",
  ".gl-bel-kicker",
  ".gl-gc-lbl",
  ".gl-quote",
  ".gl-hero h2",
  ".structure-tab",
  ".section-head h2",
  ".section-head p",
  ".cta-band h3",
  ".cta-band p",
  ".btn-primary",
  ".btn-secondary",
  ".page-footer-row span",
  ".media-hero-eyebrow",
  ".media-hero-overlay p",
  ".media-hero-hint",
  ".media-label",
  ".media-feat-caption",
].join(", ");

const guideFallbackTextSelector = [
  "main h2",
  "main h3",
  "main h4",
  "main p",
  "main li",
  "main th",
  "main td",
  "main strong",
  "main span",
  "main a",
  "footer p",
  "footer span",
  "footer a",
].join(", ");

function translateGuideElement(el, lang) {
  const base = el.dataset.i18nBase || el.textContent.trim();
  if (!base) return;
  if (!el.dataset.i18nBase) el.dataset.i18nBase = base;
  const locale = guideLiteralTranslations[base];
  if (!locale) return;
  el.textContent = resolveGuideTranslation(base, lang, locale);
}

function translateGuideText(lang) {
  document.querySelectorAll(guideTextSelector).forEach((el) => {
    translateGuideElement(el, lang);
  });

  document.querySelectorAll(guideFallbackTextSelector).forEach((el) => {
    if (el.closest(".lang-switcher, .topbar-links, .mobile-nav")) return;
    if (el.children.length > 0) return;
    translateGuideElement(el, lang);
  });

  document.querySelectorAll("img[alt]").forEach((img) => {
    const base = img.dataset.i18nAltBase || img.getAttribute("alt") || "";
    if (!base) return;
    if (!img.dataset.i18nAltBase) img.dataset.i18nAltBase = base;
    const locale = guideAttrTranslations[base];
    img.setAttribute("alt", resolveGuideTranslation(base, lang, locale));
  });

  document.querySelectorAll("[aria-label]").forEach((el) => {
    const base = el.dataset.i18nAriaBase || el.getAttribute("aria-label") || "";
    if (!base) return;
    if (!el.dataset.i18nAriaBase) el.dataset.i18nAriaBase = base;
    const locale = guideAttrTranslations[base];
    el.setAttribute("aria-label", resolveGuideTranslation(base, lang, locale));
  });

  const baseTitle = document.documentElement.dataset.i18nTitleBase || document.title;
  if (!document.documentElement.dataset.i18nTitleBase) {
    document.documentElement.dataset.i18nTitleBase = baseTitle;
  }
  const titleLocale = guideLiteralTranslations[baseTitle];
  document.title = resolveGuideTranslation(baseTitle, lang, titleLocale);

  const meta = document.querySelector('meta[name="description"]');
  if (meta) {
    const baseDesc = meta.dataset.i18nBase || meta.content;
    if (!meta.dataset.i18nBase) meta.dataset.i18nBase = baseDesc;
    const descLocale = guideLiteralTranslations[baseDesc];
    meta.content = resolveGuideTranslation(baseDesc, lang, descLocale);
  }
}

