function normalizeGuideHeader() {
  const topbar = document.querySelector(".topbar");
  const brand = topbar?.querySelector(".brand");
  const brandSub = topbar?.querySelector(".brand-sub");
  const links = topbar?.querySelector(".topbar-links");
  const actions = topbar?.querySelector(".topbar-actions");

  if (!topbar || !brand || !links) return;

  const currentPage = (window.location.pathname.split("/").pop() || "kktc-sirket-kurma.html").toLowerCase();
  topbar.id = topbar.id || "header";
  brand.classList.add("logo");
  brand.setAttribute("href", "./kktc-sirket-kurma.html");
  actions?.classList.add("header-actions");

  if (brandSub) {
    brandSub.textContent = "Şirket Kurma ve Mali Danışmanlık";
    brandSub.setAttribute("data-tr", "Şirket Kurma ve Mali Danışmanlık");
    brandSub.setAttribute("data-en", "Company Formation and Financial Advisory");
    brandSub.setAttribute("data-ru", "Регистрация компаний и финансовый консалтинг");
    brandSub.setAttribute("data-fa", "تأسيس الشركات والاستشارات المالية");
  }

  links.replaceChildren(...GUIDE_HEADER_LINKS.map((item) => {
    const link = document.createElement("a");
    const itemPage = item.href.replace("./", "").toLowerCase();
    link.href = item.href;
    link.className = `nav-link${itemPage === currentPage ? " active" : ""}`;
    link.textContent = item.tr;
    link.setAttribute("data-tr", item.tr);
    link.setAttribute("data-en", item.en);
    link.setAttribute("data-ru", item.ru);
    link.setAttribute("data-fa", item.fa);
    return link;
  }));
}

function setGuideMobileNav(open) {
  const mobileNav = document.getElementById("mobile-nav");
  const toggle = document.querySelector(".hamburger");
  if (!mobileNav || !toggle) return;

  const isMobileOpen = open && window.innerWidth <= 760;
  mobileNav.classList.toggle("open", open);
  mobileNav.setAttribute("aria-hidden", String(!open));
  toggle.classList.toggle("active", open);
  toggle.setAttribute("aria-expanded", String(open));
  document.documentElement.classList.toggle("mobile-nav-open", isMobileOpen);
  document.body.classList.toggle("mobile-nav-open", isMobileOpen);
}

function initGuideMobileHeader() {
  const topbar = document.querySelector(".topbar");
  const inner = topbar?.querySelector(".topbar-inner");
  const links = topbar?.querySelector(".topbar-links");
  const switcher = topbar?.querySelector(".lang-switcher");

  if (!topbar || !inner || !links || !switcher || document.getElementById("mobile-nav")) {
    return;
  }

  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "hamburger";
  toggle.setAttribute("aria-label", "Menu");
  toggle.setAttribute("aria-controls", "mobile-nav");
  toggle.setAttribute("aria-expanded", "false");
  toggle.innerHTML = "<span></span><span></span><span></span>";

  const mobileNav = document.createElement("div");
  mobileNav.className = "mobile-nav";
  mobileNav.id = "mobile-nav";
  mobileNav.setAttribute("aria-hidden", "true");

  const mobileNavLang = document.createElement("div");
  mobileNavLang.className = "mobile-nav-lang";
  mobileNavLang.appendChild(switcher.cloneNode(true));

  links.querySelectorAll("a").forEach((link) => {
    mobileNav.appendChild(link.cloneNode(true));
  });

  mobileNav.prepend(mobileNavLang);
  topbar.insertAdjacentElement("afterend", mobileNav);
  inner.appendChild(toggle);

  toggle.addEventListener("click", () => {
    setGuideMobileNav(!mobileNav.classList.contains("open"));
  });

  mobileNav.querySelectorAll("a").forEach((link) => {
    link.addEventListener("click", () => setGuideMobileNav(false));
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") setGuideMobileNav(false);
  });

  window.addEventListener("resize", () => {
    if (window.innerWidth > 760) setGuideMobileNav(false);
  });
}

function bindGuideLangButtons() {
  document.querySelectorAll(".lang-btn").forEach((btn) => {
    if (btn.dataset.guideLangBound === "1") return;
    btn.dataset.guideLangBound = "1";
    btn.addEventListener("click", () => {
      setGuideLang(btn.dataset.lang || "tr");
      if (btn.closest(".mobile-nav")) setGuideMobileNav(false);
    });
  });
}

function setGuideLang(lang) {
  const nextLang = ["tr", "en", "ru", "fa"].includes(lang) ? lang : "tr";

  try {
    localStorage.setItem(GUIDE_LANGUAGE_STORAGE_KEY, nextLang);
  } catch (error) {
    console.warn("Language preference could not be saved.", error);
  }

  document.documentElement.lang = nextLang;
  document.documentElement.dir = nextLang === "fa" ? "rtl" : "ltr";

  document.querySelectorAll(".lang-btn").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.lang === nextLang);
  });

  translateGuideText(nextLang);
}

const GUIDE_HEADER_ZOOM_LOCK_TOLERANCE = 0.03;

function supportsGuideHeaderZoomLock() {
  return !window.matchMedia("(pointer: coarse)").matches && (navigator.maxTouchPoints || 0) === 0;
}

function clampGuideHeaderZoom(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function getGuideHeaderBrowserZoom() {
  const screenWidth = window.screen?.width || 0;
  const innerWidth = window.innerWidth || document.documentElement.clientWidth || 0;
  let zoom = 1;

  if (screenWidth && innerWidth) {
    zoom = screenWidth / innerWidth;
  }

  if (!Number.isFinite(zoom) || zoom <= 0) zoom = 1;
  return clampGuideHeaderZoom(zoom, 0.2, 5);
}

function syncGuideHeaderZoomLock() {
  const zoom = getGuideHeaderBrowserZoom();
  const scale = clampGuideHeaderZoom(1 / zoom, 0.2, 5);
  const locked = supportsGuideHeaderZoomLock() && Math.abs(zoom - 1) > GUIDE_HEADER_ZOOM_LOCK_TOLERANCE;

  document.body.style.setProperty("--header-zoom-scale", locked ? scale.toFixed(4) : "1");
  document.body.classList.toggle("header-zoom-lock", locked);
  if (locked) setGuideMobileNav(false);
}

normalizeGuideHeader();
initGuideMobileHeader();
bindGuideLangButtons();
syncGuideHeaderZoomLock();

window.addEventListener("resize", () => {
  syncGuideHeaderZoomLock();
});

window.visualViewport?.addEventListener("resize", syncGuideHeaderZoomLock);

const initialGuideLang = (() => {
  try {
    return localStorage.getItem(GUIDE_LANGUAGE_STORAGE_KEY) || "tr";
  } catch (error) {
    return "tr";
  }
})();

setGuideLang(initialGuideLang);

